CREATE TABLE IF NOT EXISTS companies(id INTEGER PRIMARY KEY,name TEXT NOT NULL,logo_text TEXT,time_zone TEXT NOT NULL,default_theme TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS users(id INTEGER PRIMARY KEY,email TEXT NOT NULL UNIQUE,password_hash TEXT NOT NULL,full_name TEXT NOT NULL,theme TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'active');
CREATE TABLE IF NOT EXISTS company_memberships(user_id INTEGER NOT NULL,company_id INTEGER NOT NULL,role TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'active',PRIMARY KEY(user_id,company_id),FOREIGN KEY(user_id) REFERENCES users(id),FOREIGN KEY(company_id) REFERENCES companies(id));
CREATE TABLE IF NOT EXISTS departments(id INTEGER PRIMARY KEY,company_id INTEGER NOT NULL,path TEXT NOT NULL,sort_order INTEGER NOT NULL,FOREIGN KEY(company_id) REFERENCES companies(id));
CREATE TABLE IF NOT EXISTS employees(id INTEGER PRIMARY KEY,user_id INTEGER,company_id INTEGER NOT NULL,first_name TEXT NOT NULL,last_name TEXT NOT NULL,middle_name TEXT,position TEXT NOT NULL,city TEXT,internal_phone TEXT,mobile_phone TEXT,work_email TEXT NOT NULL,personal_email TEXT,show_personal_email INTEGER NOT NULL DEFAULT 0,telegram_url TEXT,mattermost_url TEXT,primary_department_id INTEGER,role TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'active',date_hired TEXT NOT NULL,last_work_day TEXT,date_dismissed TEXT,version INTEGER NOT NULL DEFAULT 1,updated_at TEXT,UNIQUE(company_id,work_email),FOREIGN KEY(user_id) REFERENCES users(id),FOREIGN KEY(company_id) REFERENCES companies(id));
CREATE TABLE IF NOT EXISTS employee_departments(employee_id INTEGER NOT NULL,department_id INTEGER NOT NULL,is_primary INTEGER NOT NULL DEFAULT 0,PRIMARY KEY(employee_id,department_id));
CREATE TABLE IF NOT EXISTS sessions(token TEXT PRIMARY KEY,user_id INTEGER NOT NULL,active_company_id INTEGER NOT NULL,expires_at DATETIME NOT NULL,FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS audit_logs(id INTEGER PRIMARY KEY AUTOINCREMENT,actor_user_id INTEGER,company_id INTEGER,action TEXT NOT NULL,entity_type TEXT NOT NULL,entity_id INTEGER,details TEXT,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP);
